      "sourcePageUrl": "https://www.town.morimachi.shizuoka.jp/gyosei/choseijoho/machinokeikaku_torikumi/5687.html",
      "sourceSha256": "34323d7b74748dd66222bdf1794b029838e9f56615dc69daae40bf40fb425669",
      "fetchedAt": "2026-10-21T08:42:38.201Z",
      "format": "html",
      "truncated": false,
      "text": "第9次森町総合計画／静岡県森町\n第9次森町総合計画\n更新日：2025年12月22日\n森町では、平成28年度から令和7年度までの10年間における、町が目指す姿と進むべき道筋を明らかにするための最上位の方針となる「第9次森町総合計画」を策定しました。まちの将来像を「住む人も訪れる人も心和(やわ)らぐ森町」と定め、「保健・医療・福祉」「教育・文化」「活力・情報発信」「産業振興」「安心・安全」「自然環境」を6つの基本目標とし、町民の皆さんと協働して各種施策に取り組んでいきます。\n第9次森町総合計画本編 (PDFファイル: 19.2MB)\n第9次森町総合計画概要版 (PDFファイル: 9.4MB)\n総合計画とは\n第8次森町総合計画\n第9次森町総合計画の策定経過について\n第9次森町総合計画の進行管理について\n1.進行管理を実施する項目について\n第9次森町総合計画においては、6つの基本の柱ごとに計15の施策の基本方向を設定しています。\n基本方向の各施策の方向における199の主な事業と31の目標指標について進行管理の対象項目とします。\n1.保健・医療・福祉\n施策の基本方向\n主な事業の数\n目標指標の数\nいつまでも「いきいき」過ごせるまちをつくる\n22\n2\n「お達者」で暮らせるまちをつくる\n28\n2\n子育て・子育ちしやすいまちをつくる\n17\n2\n2.教育・文化\n施策の基本方向\n主な事業の数\n目標指標の数\n「ひと」と「ひと」が育みあうまちをつくる\n24\n6\n歴史に学び多様な文化を継ぐまちをつくる\n13\n4\n3.活力・情報発信\n施策の基本方向\n主な事業の数\n目標指標の数\n調和のとれた居心地のよいまちをつくる\n9\n1\n町の魅力や情報を広く効果的に発信するまちをつくる\n8\n2\n地域の宝・資源を最大限にいかしたまちをつくる\n12\n1\n4.産業振興\n施策の基本方向\n主な事業の数\n目標指標の数\n活力が持続できるまちをつくる\n17\n3\n新たな活力が生まれるまちをつくる\n4\n1\n5.安心・安全\n施策の基本方向\n主な事業の数\n目標指標の数\n安全・快適に暮らせるまちをつくる\n16\n3\n災害に強い、地域防災力の高いまちをつくる\n9\n1\nコミュニティ豊かな地域活動が活発なまちをつくる\n4\n1\n6.自然環境\n施策の基本方向\n主な事業の数\n目標指標の数\n緑豊かな自然あふれるまちをつくる\n9\n1\n自然環境と共存するまちをつくる\n7\n1\n2.進行管理の実施方法について\n担当各課に職場進行管理者を置き、主な事業の各年度における進行状況を、S：計画以上に進捗した、A：計画通り進捗した、B：概ね計画通り進捗した、C：計画通り進捗しなかった（未着手含む）の4段階で評価を実施します。またそれぞれの目標指標について各年度の実績値の確認を行います。\n平成29年度進行管理状況・評価について\n主な事業 平成29年度評価一覧表 (PDFファイル: 41.3KB)\n主な事業 平成29年度評価内訳 (PDFファイル: 132.6KB)\n目標指標 平成29年度進捗実績 (PDFファイル: 68.4KB)\n平成30年度進行管理状況・評価について\n主な事業 平成30年度評価一覧表 (PDFファイル: 56.5KB)\n主な事業 平成30年度評価内訳 (PDFファイル: 133.8KB)\n目標指標 平成30年度進捗実績 (PDFファイル: 85.1KB)\n令和元年度進行管理状況・評価について\n主な事業 令和元年度評価一覧表 (PDFファイル: 56.9KB)\n主な事業 令和元年度評価内訳 (PDFファイル: 373.3KB)\n目標指標 令和元年度進捗実績 (PDFファイル: 85.8KB)\n令和2年度進行管理状況・評価について\n主な事業 令和2年度評価一覧表 (PDFファイル: 56.8KB)\n主な事業 令和2年度評価内訳 (PDFファイル: 146.6KB)\n目標指標 令和2年度進捗実績 (PDFファイル: 86.4KB)\n令和3年度進行管理状況・評価について\n主な事業 令和3年度評価一覧表 (PDFファイル: 113.6KB)\n主な事業 令和3年度評価内訳 (PDFファイル: 133.0KB)\n目標指標 令和3年度進捗実績 (PDFファイル: 120.4KB)\n令和4年度進行管理状況・評価について\n主な事業 令和4年度評価一覧表 (PDFファイル: 62.1KB)\n主な事業 令和4年度評価内訳 (PDFファイル: 134.1KB)\n目標指標 令和4年度進捗実績 (PDFファイル: 156.3KB)\n令和5年度進行管理状況・評価について\n主な事業 令和5年度評価一覧表 (PDFファイル: 94.1KB)\n主な事業 令和5年度評価内訳 (PDFファイル: 410.3KB)\n目標指標 令和5年度進捗実績 (PDFファイル: 163.0KB)\n令和6年度進行管理状況・評価について\n主な事業 令和6年度評価一覧表 (PDFファイル: 95.0KB)\n主な事業 令和6年度評価内訳 (PDFファイル: 429.4KB)\n目標指標 令和6年度進捗実績 (PDFファイル: 161.1KB)\n第9次森町総合計画 目標指標 進捗度及び評価結果 (PDFファイル: 156.9KB)\nこのページに関する"
